ALTER TABLE product ADD COLUMN "PurchasePrice" numeric;
ALTER TABLE product ADD CONSTRAINT "CK_product_price" CHECK ("PurchasePrice">=0 AND "PurchasePrice"<1000000000);
CREATE TABLE department ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Name" text NOT NULL,"TypeId" integer NOT NULL REFERENCES class_node ON DELETE RESTRICT);
CREATE TABLE work_center ("Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Name" text NOT NULL,"TypeId" integer NOT NULL REFERENCES class_node ON DELETE RESTRICT,"DepartmentId" integer NOT NULL REFERENCES department ON DELETE RESTRICT);
CREATE TABLE tech_step (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Kind" text NOT NULL CHECK ("Kind" IN ('purchase','production')),
 "ProductId" integer NOT NULL REFERENCES product ON DELETE RESTRICT,"ResultName" text NOT NULL CHECK(length(trim("ResultName"))>0),"UnitId" integer NOT NULL REFERENCES measure_unit ON DELETE RESTRICT,
 "Number" integer NOT NULL,"OperationId" integer REFERENCES class_node ON DELETE RESTRICT,"WorkCenterId" integer REFERENCES work_center ON DELETE RESTRICT,"ProfessionId" integer REFERENCES class_node ON DELETE RESTRICT,"QualificationId" integer REFERENCES enum_value ON DELETE RESTRICT,
 "Tooling" text NOT NULL,"SetupMinutes" numeric NOT NULL CHECK("SetupMinutes">=0 AND "SetupMinutes"<1000000000),"UnitMinutes" numeric NOT NULL CHECK("UnitMinutes">=0 AND "UnitMinutes"<1000000000),"HourlyRate" numeric NOT NULL CHECK("HourlyRate">=0 AND "HourlyRate"<1000000000),
 CHECK("Kind"='purchase' OR ("Number">0 AND "OperationId" IS NOT NULL AND "WorkCenterId" IS NOT NULL AND "ProfessionId" IS NOT NULL AND "QualificationId" IS NOT NULL))
);
CREATE TABLE tech_input (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"StepId" integer NOT NULL REFERENCES tech_step ON DELETE RESTRICT,"SourceId" integer NOT NULL REFERENCES tech_step ON DELETE RESTRICT,
 "Amount" numeric NOT NULL CHECK("Amount">0 AND "Amount"<1000000000),"ForQuantity" numeric NOT NULL CHECK("ForQuantity">0 AND "ForQuantity"<1000000000),"ParameterId" integer REFERENCES parameter_definition ON DELETE RESTRICT,
 UNIQUE("StepId","SourceId"),CHECK("StepId"<>"SourceId")
);
CREATE TABLE tech_route_setting (
 "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,"Name" text NOT NULL CHECK(length(trim("Name"))>0),"ProductId" integer NOT NULL REFERENCES product ON DELETE RESTRICT,
 "RevisionId" integer REFERENCES bom_revision ON DELETE RESTRICT,"FinalStepId" integer NOT NULL REFERENCES tech_step ON DELETE RESTRICT,
 "Kind" text NOT NULL CHECK("Kind" IN ('standalone','template','application')),
 "ParameterId" integer REFERENCES parameter_definition ON DELETE RESTRICT,"ParameterValue" numeric,
 CHECK(("ParameterId" IS NULL AND "ParameterValue" IS NULL) OR ("ParameterId" IS NOT NULL AND "ParameterValue" IS NOT NULL AND "ParameterValue">0 AND "ParameterValue"<1000000000))
);
-- All writes share the catalog lock, including direct SQL clients.
CREATE FUNCTION route_lock() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN PERFORM pg_advisory_xact_lock(734021,1); RETURN NULL; END $$;
CREATE FUNCTION route_branch(id int, code text) RETURNS boolean LANGUAGE sql STABLE AS $$
 WITH RECURSIVE parents AS (SELECT "Id","ParentId","ShortName" FROM class_node WHERE "Id"=id UNION ALL SELECT c."Id",c."ParentId",c."ShortName" FROM class_node c JOIN parents p ON p."ParentId"=c."Id") SELECT EXISTS(SELECT 1 FROM parents WHERE "ShortName"=code) $$;
INSERT INTO class_node("Name","ShortName","IsTerminal","SortOrder","ParentId","MeasureUnitId") VALUES
 ('Технологические операции','route_operations',false,100,NULL,NULL),('Профессии','route_professions',false,101,NULL,NULL),('Типы подразделений','route_departments',false,102,NULL,NULL),('Типы рабочих центров','route_centers',false,103,NULL,NULL);
INSERT INTO class_node("Name","ShortName","IsTerminal","SortOrder","ParentId","MeasureUnitId")
 SELECT v.name,v.code,true,0,c."Id",NULL FROM (VALUES ('Монтаж','route_assembly','route_operations'),('Монтажник','route_assembler','route_professions'),('Сборочный участок','route_department','route_departments'),('Монтажный пост','route_center','route_centers')) v(name,code,parent) JOIN class_node c ON c."ShortName"=v.parent;
INSERT INTO enum_class("Name","ShortName","ValueType","SortOrder","MeasureUnitId") VALUES ('Квалификация технолога','route_qualification',1,100,NULL);
INSERT INTO enum_value("EnumClassId","StringValue","NumberValue","IconValue","DisplayName","SortOrder") SELECT "Id",'3 разряд',NULL,NULL,'3 разряд',0 FROM enum_class WHERE "ShortName"='route_qualification';
INSERT INTO department("Name","TypeId") SELECT 'Сборочный участок',"Id" FROM class_node WHERE "ShortName"='route_department';
INSERT INTO work_center("Name","TypeId","DepartmentId") SELECT 'Монтажный пост',c."Id",d."Id" FROM class_node c CROSS JOIN department d WHERE c."ShortName"='route_center';
CREATE FUNCTION route_validate() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM product WHERE route_branch("ClassNodeId",'route_operations') OR route_branch("ClassNodeId",'route_professions') OR route_branch("ClassNodeId",'route_departments') OR route_branch("ClassNodeId",'route_centers')) THEN RAISE EXCEPTION 'Служебный класс нельзя выбирать для изделия.'; END IF;
 IF EXISTS(SELECT 1 FROM department WHERE NOT route_branch("TypeId",'route_departments')) OR EXISTS(SELECT 1 FROM work_center WHERE NOT route_branch("TypeId",'route_centers')) THEN RAISE EXCEPTION 'Неверный тип подразделения или центра.'; END IF;
 IF EXISTS(SELECT 1 FROM tech_step s JOIN product p ON p."Id"=s."ProductId" JOIN class_node c ON c."Id"=p."ClassNodeId" WHERE s."UnitId" IS DISTINCT FROM c."MeasureUnitId") THEN RAISE EXCEPTION 'Единица позиции не соответствует изделию.'; END IF;
 IF EXISTS(SELECT 1 FROM tech_step s WHERE s."Kind"='production' AND (NOT route_branch(s."OperationId",'route_operations') OR NOT route_branch(s."ProfessionId",'route_professions') OR NOT EXISTS(SELECT 1 FROM enum_value v JOIN enum_class c ON c."Id"=v."EnumClassId" WHERE v."Id"=s."QualificationId" AND c."ShortName"='route_qualification'))) THEN RAISE EXCEPTION 'Неверный класс операции, профессия или квалификация.'; END IF;
 IF EXISTS(SELECT 1 FROM tech_input i JOIN tech_step s ON s."Id"=i."StepId" WHERE s."Kind"<>'production') THEN RAISE EXCEPTION 'Закупная позиция не может иметь входы.'; END IF;
 IF EXISTS(WITH RECURSIVE walk AS (SELECT "StepId" start,"SourceId" node,ARRAY["StepId"] path FROM tech_input UNION ALL SELECT w.start,i."SourceId",w.path||w.node FROM walk w JOIN tech_input i ON i."StepId"=w.node WHERE NOT w.node=ANY(w.path)) SELECT 1 FROM walk WHERE node=ANY(path)) THEN RAISE EXCEPTION 'Цикл в технологическом маршруте.'; END IF;
 IF EXISTS(SELECT 1 FROM tech_route_setting r JOIN tech_step s ON s."Id"=r."FinalStepId" WHERE s."Kind"<>'production' OR s."ProductId"<>r."ProductId" OR (r."RevisionId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM bom_revision b WHERE b."Id"=r."RevisionId" AND b."ProductId"=r."ProductId" AND b."IsConfigured" AND b."IsFinalized" AND b."UnitId"=s."UnitId"))) THEN RAISE EXCEPTION 'Итоговая позиция или исполнение другого изделия.'; END IF;
 IF EXISTS(SELECT 1 FROM tech_route_setting r WHERE r."ParameterId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM parameter_definition p WHERE p."Id"=r."ParameterId" AND p."ValueType" IN (1,2))) THEN RAISE EXCEPTION 'Нужен числовой параметр.'; END IF;
 IF EXISTS(SELECT 1 FROM tech_route_setting r WHERE r."Kind"='application' AND NOT EXISTS(SELECT 1 FROM tech_route_setting t WHERE t."Kind"='template' AND t."FinalStepId"=r."FinalStepId" AND t."ParameterId" IS NOT DISTINCT FROM r."ParameterId")) THEN RAISE EXCEPTION 'Применение должно ссылаться на типовой процесс.'; END IF;
 IF EXISTS(WITH RECURSIVE walk AS (SELECT "Id" rid,"FinalStepId" sid,"ParameterId" pid FROM tech_route_setting UNION SELECT w.rid,i."SourceId",w.pid FROM walk w JOIN tech_input i ON i."StepId"=w.sid) SELECT 1 FROM walk w JOIN tech_input i ON i."StepId"=w.sid JOIN tech_step s ON s."Id"=i."SourceId" JOIN parameter_definition p ON p."Id"=i."ParameterId" WHERE i."ParameterId" IS DISTINCT FROM w.pid OR p."ValueType" NOT IN (1,2) OR p."MeasureUnitId" IS DISTINCT FROM s."UnitId") THEN RAISE EXCEPTION 'Параметр входа не соответствует настройке или единице.'; END IF;
 RETURN NULL;
END $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['department','work_center','tech_step','tech_input','tech_route_setting','class_node','parameter_definition','enum_value','enum_class','product'] LOOP
 EXECUTE format('CREATE TRIGGER route_lock BEFORE INSERT OR UPDATE OR DELETE ON %I FOR EACH STATEMENT EXECUTE FUNCTION route_lock()',t);
 EXECUTE format('CREATE CONSTRAINT TRIGGER route_validate AFTER INSERT OR UPDATE OR DELETE ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION route_validate()',t);
 END LOOP; END $$;
CREATE FUNCTION route_product_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF route_branch(NEW."ClassNodeId",'route_operations') OR route_branch(NEW."ClassNodeId",'route_professions') OR route_branch(NEW."ClassNodeId",'route_departments') OR route_branch(NEW."ClassNodeId",'route_centers') THEN RAISE EXCEPTION 'Служебный класс нельзя выбирать для изделия.'; END IF;
 IF TG_OP='UPDATE' AND NEW."PurchasePrice" IS NOT NULL AND (SELECT "MeasureUnitId" FROM class_node WHERE "Id"=NEW."ClassNodeId") IS DISTINCT FROM (SELECT "MeasureUnitId" FROM class_node WHERE "Id"=OLD."ClassNodeId") THEN RAISE EXCEPTION 'Перед сменой единицы очистите закупочную цену.'; END IF; RETURN NEW;
END $$;
CREATE TRIGGER route_product_guard BEFORE INSERT OR UPDATE ON product FOR EACH ROW EXECUTE FUNCTION route_product_guard();
CREATE FUNCTION route_unit_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW."MeasureUnitId" IS DISTINCT FROM OLD."MeasureUnitId" AND EXISTS(SELECT 1 FROM product WHERE "ClassNodeId"=NEW."Id" AND "PurchasePrice" IS NOT NULL) THEN RAISE EXCEPTION 'Перед сменой единицы очистите цены изделий класса.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER route_unit_guard BEFORE UPDATE ON class_node FOR EACH ROW EXECUTE FUNCTION route_unit_guard();
CREATE FUNCTION add_product(p_name text,p_short text,p_class integer,p_price numeric) RETURNS integer LANGUAGE sql AS $$ INSERT INTO product("Name","ShortName","ClassNodeId","PurchasePrice") VALUES(p_name,p_short,p_class,p_price) RETURNING "Id" $$;
CREATE FUNCTION set_product_price(p_id int,p_price numeric) RETURNS boolean LANGUAGE plpgsql AS $$ BEGIN UPDATE product SET "PurchasePrice"=p_price WHERE "Id"=p_id; RETURN FOUND; END $$;
-- A single traversal context for all calculations. Each path carries its own demand.
CREATE FUNCTION find_tm(product_id int, quantity numeric, setting_id int)
RETURNS TABLE(path int[],depth int,step_id int,parent_id int,required_quantity numeric,kind text,number int,result_name text,unit text,source_product_id int) LANGUAGE plpgsql STABLE AS $$
DECLARE r tech_route_setting;
BEGIN
 SELECT * INTO r FROM tech_route_setting WHERE "Id"=setting_id AND "ProductId"=product_id;
 IF NOT FOUND OR quantity IS NULL OR quantity<=0 OR quantity>=1000000000 THEN RAISE EXCEPTION 'Выберите маршрут изделия и положительный размер партии.'; END IF;
 RETURN QUERY WITH RECURSIVE walk AS (
 SELECT ARRAY[r."FinalStepId"] path,0 depth,r."FinalStepId" sid,NULL::int parent,quantity q
 UNION ALL SELECT w.path||i."SourceId",w.depth+1,i."SourceId",w.sid,w.q*(CASE WHEN i."ParameterId" IS NULL THEN i."Amount" ELSE r."ParameterValue" END)/i."ForQuantity" FROM walk w JOIN tech_input i ON i."StepId"=w.sid
 ) SELECT w.path,w.depth,s."Id",w.parent,w.q,s."Kind",s."Number",s."ResultName",u."ShortName"::text,s."ProductId" FROM walk w JOIN tech_step s ON s."Id"=w.sid JOIN measure_unit u ON u."Id"=s."UnitId" ORDER BY w.path;
END $$;
CREATE FUNCTION mr_q(operation_id int, quantity numeric, setting_id int)
RETURNS TABLE(source_id int,name text,kind text,unit text,amount numeric,for_quantity numeric,required_quantity numeric) LANGUAGE plpgsql STABLE AS $$
DECLARE r tech_route_setting;
BEGIN
 SELECT * INTO r FROM tech_route_setting WHERE "Id"=setting_id;
 IF NOT EXISTS(SELECT 1 FROM find_tm(r."ProductId",quantity,setting_id) WHERE step_id=operation_id AND find_tm.kind='production') THEN RAISE EXCEPTION 'Операция не принадлежит выбранному маршруту.'; END IF;
 RETURN QUERY SELECT s."Id",s."ResultName",s."Kind",u."ShortName"::text,CASE WHEN i."ParameterId" IS NULL THEN i."Amount" ELSE r."ParameterValue" END,i."ForQuantity",quantity*(CASE WHEN i."ParameterId" IS NULL THEN i."Amount" ELSE r."ParameterValue" END)/i."ForQuantity" FROM tech_input i JOIN tech_step s ON s."Id"=i."SourceId" JOIN measure_unit u ON u."Id"=s."UnitId" WHERE i."StepId"=operation_id ORDER BY s."Number",s."Id";
END $$;
CREATE FUNCTION sum_mr(p_product int, quantity numeric, setting_id int)
RETURNS TABLE(product_id int,name text,unit text,required_quantity numeric,price numeric,cost numeric) LANGUAGE sql STABLE AS $$
 SELECT p."Id",p."Name"::text,f.unit,sum(f.required_quantity),p."PurchasePrice",sum(f.required_quantity)*p."PurchasePrice" FROM find_tm($1,$2,$3) f JOIN product p ON p."Id"=f.source_product_id WHERE f.kind='purchase' GROUP BY p."Id",f.unit ORDER BY p."Name" $$;
CREATE FUNCTION tr_to(product_id int, quantity numeric, setting_id int)
RETURNS TABLE(step_id int,number int,name text,profession text,required_quantity numeric,setup_minutes numeric,unit_minutes numeric,minutes numeric,hourly_rate numeric,cost numeric) LANGUAGE sql STABLE AS $$
 WITH demand AS (SELECT f.step_id,sum(f.required_quantity) q FROM find_tm($1,$2,$3) f WHERE f.kind='production' GROUP BY f.step_id)
 SELECT s."Id",s."Number",s."ResultName",c."Name"::text,d.q,s."SetupMinutes",s."UnitMinutes",s."SetupMinutes"+s."UnitMinutes"*d.q,s."HourlyRate",(s."SetupMinutes"+s."UnitMinutes"*d.q)*s."HourlyRate"/60 FROM demand d JOIN tech_step s ON s."Id"=d.step_id JOIN class_node c ON c."Id"=s."ProfessionId" ORDER BY s."Number",s."Id" $$;

CREATE INDEX "IX_department_TypeId" ON department("TypeId");
CREATE INDEX "IX_work_center_TypeId" ON work_center("TypeId");
CREATE INDEX "IX_work_center_DepartmentId" ON work_center("DepartmentId");
CREATE INDEX "IX_tech_step_ProductId" ON tech_step("ProductId");
CREATE INDEX "IX_tech_step_UnitId" ON tech_step("UnitId");
CREATE INDEX "IX_tech_step_OperationId" ON tech_step("OperationId");
CREATE INDEX "IX_tech_step_WorkCenterId" ON tech_step("WorkCenterId");
CREATE INDEX "IX_tech_step_ProfessionId" ON tech_step("ProfessionId");
CREATE INDEX "IX_tech_step_QualificationId" ON tech_step("QualificationId");
CREATE INDEX "IX_tech_input_SourceId" ON tech_input("SourceId");
CREATE INDEX "IX_tech_input_ParameterId" ON tech_input("ParameterId");
CREATE INDEX "IX_tech_route_setting_ProductId" ON tech_route_setting("ProductId");
CREATE INDEX "IX_tech_route_setting_RevisionId" ON tech_route_setting("RevisionId");
CREATE INDEX "IX_tech_route_setting_ParameterId" ON tech_route_setting("ParameterId");

CREATE UNIQUE INDEX "UX_tech_route_owner" ON tech_route_setting("FinalStepId") WHERE "Kind"<>'application';
